{
  "features": [
    {
      "feature_name": "pos_max_dpd_def",
      "rationale": "Captures the maximum severity of payment delinquency (with tolerance) across all POS/Cash loans, indicating peak financial stress.",
      "source_tables": [
        "POS_CASH_balance"
      ],
      "python_code": "def compute_pos_max_dpd_def(app_train, bureau, bureau_bal, prev_app, install, cc_bal, pos_cash):\n    agg = pos_cash.groupby('SK_ID_CURR').agg(val=('SK_DPD_DEF', 'max')).reset_index()\n    result = app_train[['SK_ID_CURR']].merge(agg, on='SK_ID_CURR', how='left')\n    result['val'] = result['val'].fillna(0)\n    return result.set_index('SK_ID_CURR')['val'].rename('pos_max_dpd_def')"
    },
    {
      "feature_name": "pos_active_contract_ratio",
      "rationale": "Measures the proportion of time POS/Cash loans were active, reflecting ongoing debt burden and repayment commitment.",
      "source_tables": [
        "POS_CASH_balance"
      ],
      "python_code": "def compute_pos_active_contract_ratio(app_train, bureau, bureau_bal, prev_app, install, cc_bal, pos_cash):\n    pos_cash['is_active'] = (pos_cash['NAME_CONTRACT_STATUS'] == 'Active').astype(int)\n    agg = pos_cash.groupby('SK_ID_CURR').agg(active_count=('is_active', 'sum'), total_count=('is_active', 'count')).reset_index()\n    agg['val'] = agg['active_count'] / (agg['total_count'] + 1)\n    result = app_train[['SK_ID_CURR']].merge(agg[['SK_ID_CURR', 'val']], on='SK_ID_CURR', how='left')\n    result['val'] = result['val'].fillna(0)\n    return result.set_index('SK_ID_CURR')['val'].rename('pos_active_contract_ratio')"
    },
    {
      "feature_name": "pos_future_instalment_mean",
      "rationale": "Indicates the average remaining installment count, serving as a proxy for the future cash flow commitment of the borrower.",
      "source_tables": [
        "POS_CASH_balance"
      ],
      "python_code": "def compute_pos_future_instalment_mean(app_train, bureau, bureau_bal, prev_app, install, cc_bal, pos_cash):\n    agg = pos_cash.groupby('SK_ID_CURR').agg(val=('CNT_INSTALMENT_FUTURE', 'mean')).reset_index()\n    result = app_train[['SK_ID_CURR']].merge(agg, on='SK_ID_CURR', how='left')\n    result['val'] = result['val'].fillna(0)\n    return result.set_index('SK_ID_CURR')['val'].rename('pos_future_instalment_mean')"
    },
    {
      "feature_name": "pos_dpd_def_std",
      "rationale": "Quantifies the volatility in delinquency behavior, where high variance suggests inconsistent repayment habits and higher risk.",
      "source_tables": [
        "POS_CASH_balance"
      ],
      "python_code": "def compute_pos_dpd_def_std(app_train, bureau, bureau_bal, prev_app, install, cc_bal, pos_cash):\n    agg = pos_cash.groupby('SK_ID_CURR').agg(val=('SK_DPD_DEF', 'std')).reset_index()\n    result = app_train[['SK_ID_CURR']].merge(agg, on='SK_ID_CURR', how='left')\n    result['val'] = result['val'].fillna(0)\n    return result.set_index('SK_ID_CURR')['val'].rename('pos_dpd_def_std')"
    },
    {
      "feature_name": "pos_recent_dpd_def",
      "rationale": "Focuses on the most recent month's delinquency status, as recent payment behavior is a strong predictor of immediate default risk.",
      "source_tables": [
        "POS_CASH_balance"
      ],
      "python_code": "def compute_pos_recent_dpd_def(app_train, bureau, bureau_bal, prev_app, install, cc_bal, pos_cash):\n    pos_cash = pos_cash.copy()\n    pos_cash['is_recent'] = (pos_cash['MONTHS_BALANCE'] == -1).astype(int)\n    agg = pos_cash.groupby('SK_ID_CURR').agg(val=('SK_DPD_DEF', 'max')).reset_index()\n    # Note: This simple max might not strictly be 'recent' if multiple -1 exist or if we want the specific row.\n    # Better approach: Filter for -1 first, then aggregate.\n    recent_pos = pos_cash[pos_cash['MONTHS_BALANCE'] == -1]\n    agg = recent_pos.groupby('SK_ID_CURR').agg(val=('SK_DPD_DEF', 'max')).reset_index()\n    result = app_train[['SK_ID_CURR']].merge(agg, on='SK_ID_CURR', how='left')\n    result['val'] = result['val'].fillna(0)\n    return result.set_index('SK_ID_CURR')['val'].rename('pos_recent_dpd_def')"
    }
  ]
}
